conditioner:
MiniT2IConditioner (must be PORTED into src/conditioning/conditioner.hpp; it is not in the fork yet). It wraps a single T5-XXL encoder ("text_encoders.t5xxl.transformer") plus a T5UniGramTokenizer, prompt_length=256, and returns c_crossattn (T5 hidden states, dim 1024 × 256) and c_vector. Port it to fork convention by threading params_backend and using the fork T5Runner signature `T5Runner(backend, params_backend, tensor_storage_map, prefix, is_umt5=false)`:

struct MiniT2IConditioner : public Conditioner {
    T5UniGramTokenizer tokenizer;
    std::shared_ptr<T5Runner> t5;
    size_t prompt_length = 256;

    MiniT2IConditioner(ggml_backend_t backend,
                       ggml_backend_t params_backend,
                       const String2TensorStorage& tensor_storage_map = {}) {
        bool use_t5 = false;
        for (const auto& pair : tensor_storage_map) {
            if (pair.first.find("text_encoders.t5xxl") != std::string::npos) { use_t5 = true; break; }
        }
        if (!use_t5) { LOG_WARN("No MiniT2I T5 text encoder provided"); return; }
        t5 = std::make_shared<T5Runner>(backend, params_backend, tensor_storage_map,
                                        "text_encoders.t5xxl.transformer", false);
    }
    // ... keep the rest of upstream MiniT2IConditioner verbatim (get_param_tensors,
    // set_* delegations, get_learned_condition) — those already call T5Runner methods that
    // exist in the fork. Drop the trailing `weight_manager` arg everywhere it appears.
};

